// Port of linuxdoom-1.10/r_defs.h seg_t (lines 240–258).
// A line segment generated by the BSP builder: a portion of a linedef
// (after splits) inside one subsector. The renderer (r_segs) draws
// these directly; the playsim only consults them via subsectors.
package doom.render;

public final class Seg {

    public Vertex v1;
    public Vertex v2;

    public int offset; // fixed_t — texture column offset along the linedef

    public int angle;  // angle_t — orientation (BAM-encoded)

    public Side sidedef;
    public Line linedef;

    // Sector references. Could be retrieved from the linedef, but the
    // C caches them here. backsector is null for one-sided segs.
    public Sector frontsector;
    public Sector backsector;
}
